<?php
require_once __DIR__.'/../includes/module-shell.php';moduleReady('performance_goals',$user,'Goals & performance');$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$action=$_POST['action']??'';if($action==='create'){$title=sanitizeString($_POST['title']??'',200);$due=sanitizeDate($_POST['due_date']??'');if(!$title||!$due||$due<date('Y-m-d')){$message='Enter a goal and a valid future deadline.';}else{$db->prepare('INSERT INTO performance_goals(user_id,title,due_date) VALUES(?,?,?)')->execute([$user['id'],$title,$due]);auditLog('goal_create','performance_goals',(int)$db->lastInsertId());$message='Goal created.';}}elseif($action==='progress'){$progress=sanitizeInt($_POST['progress']??'',0,100);$id=sanitizeInt($_POST['id']??0,1);if($progress===null||!$id){$message='Choose progress between 0 and 100.';}else{$q=$db->prepare('UPDATE performance_goals SET progress=? WHERE id=? AND user_id=?');$q->execute([$progress,$id,$user['id']]);$message='Your progress has been saved.';auditLog('goal_progress','performance_goals',$id);}}else{http_response_code(400);$message='Invalid action.';}}
$q=$db->prepare('SELECT * FROM performance_goals WHERE user_id=? ORDER BY due_date');$q->execute([$user['id']]);$goals=$q->fetchAll();moduleStart('Goals & performance',$user,$message);?>
<div style="margin-bottom:20px"><a class="btn btn-outline" href="/employee/reviews.php">Performance review cycles</a></div><div class="card" style="margin-bottom:24px"><div class="card-header"><h3>Make your next move.</h3></div><form class="card-body" method="post"><?php moduleToken();?><input type="hidden" name="action" value="create"><div class="grid-2"><div class="form-group"><label>Goal</label><input name="title" class="form-control" maxlength="200" placeholder="What do you want to achieve?" required></div><div class="form-group"><label>Target date</label><input name="due_date" class="form-control" type="date" min="<?=date('Y-m-d')?>" required></div></div><button class="btn btn-primary">Create goal</button></form></div><div class="module-grid"><?php foreach($goals as $goal):?><div class="card"><div class="card-body"><div class="eyebrow">Due <?=e($goal['due_date'])?></div><h3><?=e($goal['title'])?></h3><progress value="<?=(int)$goal['progress']?>" max="100" style="width:100%;accent-color:var(--cyan);margin:20px 0" aria-label="Goal progress"></progress><form method="post"><?php moduleToken();?><input type="hidden" name="action" value="progress"><input type="hidden" name="id" value="<?=(int)$goal['id']?>"><label>Progress (%)</label><input class="form-control" name="progress" type="number" min="0" max="100" value="<?=(int)$goal['progress']?>" required><button class="btn btn-outline" style="margin-top:12px">Save progress</button></form></div></div><?php endforeach;?></div><?php if(!$goals):?><div class="card empty-state">Start with one meaningful goal. Your progress will appear here.</div><?php endif;moduleEnd();
